{"file_path":"tests/test_spec.py","content":""""Regression tests for all ten sections of SPEC.md."""

import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


# Section 1: None remains in the denominator and is not flagged.
def test_monitor_flag_rate_none_values():
    events = [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    assert monitor_flag_rate(events) == pytest.approx(1 / 3)
    assert monitor_flag_rate([{"flagged": None}]) == 0.0


@pytest.mark.parametrize("flags, expected", [([], 0.0), ([False], 0.0), ([True], 1.0)])
def test_monitor_flag_rate_boundaries(flags, expected):
    rate = monitor_flag_rate([{"flagged": flag} for flag in flags])
    assert rate == expected
    assert isinstance(rate, float)


# Section 2: weight transcripts, not groups, including unknown flags.
def test_pooled_flag_rate_unequal_groups():
    groups = {
        "small": [{"flagged": True}],
        "large": [{"flagged": False}, {"flagged": None}, {"flagged": False}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_flag_rate_no_transcripts(groups):
    rate = pooled_flag_rate(groups)
    assert rate == 0.0
    assert isinstance(rate, float)


# Section 3: exactly the requested number of trailing entries.
@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 0, 0), ([], 5, 0)],
)
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


# Section 4: field whitespace, all flag values, skipped lines and error positions.
def test_parse_transcript_log_flags_and_whitespace():
    assert parse_transcript_log(["  a  ,  -2 , 1 \n", " b , 0 , 0 ", " c , 3 ,  \n"]) == [
        event("a", -2, True), event("b", 0, False), event("c", 3, None),
    ]


def test_parse_transcript_log_skips_blank_and_comment_lines():
    lines = ["", " \t\n", "# comment", " \t# not,a,record,at,all", "a,1,1"]
    assert parse_transcript_log(iter(lines)) == [event("a", 1, True)]
    assert parse_transcript_log(lines[:-1]) == []
    assert parse_transcript_log([]) == []
    # A hash within an id is not a comment.
    assert parse_transcript_log(["a#b,1,0"]) == [event("a#b", 1, False)]


@pytest.mark.parametrize("bad_line", ["a", "a,1", "a,1,0,extra", "a,no,1", "a,1.5,0", "a,,0"])
@pytest.mark.parametrize("prefix", [[], ["", "  ", " # comment", "ok,2,1"]])
def test_parse_transcript_log_errors_include_input_line_number(bad_line, prefix):
    with pytest.raises(ValueError, match=rf"\bline {len(prefix) + 1}\b"):
        parse_transcript_log(prefix + [bad_line])


# Section 5: last input occurrence wins, not first or latest day.
def test_dedupe_transcripts_duplicate_ids_keep_last():
    events = [
        event("x", 10, True),
        event("b", 2, True),
        event("x", 8, False),
        event("a", 2, None),
        event("x", 1, None),
        event("b", 2, False),
    ]
    assert dedupe_transcripts(events) == [events[4], events[3], events[5]]


def test_dedupe_transcripts_empty_and_unique():
    assert dedupe_transcripts([]) == []
    events = [event("b", 2, False), event("z", 1, True), event("a", 2, True)]
    assert dedupe_transcripts(events) == [events[1], events[2], events[0]]


# Section 6: inclusive range, multiple flags per day, missing days and exclusions.
def test_daily_flag_counts_range():
    events = [
        event("outside-before", 0, True),
        event("last", 5, True),
        event("first", 1, True),
        event("first-again", 1, True),
        event("unknown", 2, None),
        event("unflagged", 3, False),
        event("outside-after", 6, True),
    ]
    assert daily_flag_counts(events, 1, 5) == [2, 0, 0, 0, 1]
    assert daily_flag_counts(events, 1, 1) == [2]
    assert daily_flag_counts(events, 5, 1) == []


@pytest.mark.parametrize("start, end, expected", [(1, 3, [0, 0, 0]), (2, 2, [0]), (3, 1, [])])
def test_daily_flag_counts_no_events(start, end, expected):
    assert daily_flag_counts([], start, end) == expected


# Section 7: rounding, pooled weighting, nonempty groups and calendar-day windows.
@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (3, 1), (6, 4), (20, 4)])
def test_monitor_summary(days, recent):
    groups = {
        "a": [event("a", 1, True), event("b", 2, True), event("c", 2, True),
              event("d", 3, None), event("e", 6, False)],
        "b": [event("f", 4, True)],
        "empty": [],
    }
    assert monitor_summary(groups, days) == {"rate": 0.667, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_no_transcripts(groups):
    assert monitor_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


# Section 8: descending rates, ascending names on ties, and no empty groups.
@pytest.mark.parametrize(
    "n, expected",
    [(0, []), (1, ["best"]), (3, ["best", "a", "z"]), (10, ["best", "a", "z", "zero"])],
)
def test_top_flagged_groups(n, expected):
    groups = {
        "z": [{"flagged": True}, {"flagged": None}],
        "zero": [{"flagged": False}],
        "empty": [],
        "a": [{"flagged": False}, {"flagged": True}],
        "best": [{"flagged": True}],
    }
    assert top_flagged_groups(groups, n) == expected


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_top_flagged_groups_no_transcripts(groups):
    assert top_flagged_groups(groups, 5) == []


# Section 9: ordered keys and None only for empty groups.
def test_flag_rate_by_group():
    groups = {
        "z": [],
        "c": [{"flagged": None}],
        "b": [{"flagged": True}, {"flagged": None}, {"flagged": False}],
        "a": [{"flagged": True}],
    }
    rates = flag_rate_by_group(groups)
    assert list(rates) == ["a", "b", "c", "z"]
    assert rates == {"a": 1.0, "b": 1 / 3, "c": 0.0, "z": None}
    assert flag_rate_by_group({}) == {}


# Section 10: nonpositive entries break streaks; count days, not flag totals.
@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, -1, 0], 0), ([1, 2, 3], 3), ([1, 0, 1], 1),
     ([1, 2, 0, 3, 4, 5, 0, 1], 3), ([1, -1, 2, 3], 2), ([0, 5, 6], 2)],
)
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
